window.kbPageData["views/entry/k-e5c60b39955e2776"] = {"key":"entry/k-e5c60b39955e2776","state":{"route":"entry/k-e5c60b39955e2776"},"node":{"id":"k-e5c60b39955e2776","mode":"k","title":"建设项目“未批先建”的行政处罚追责期限","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["建设项目未批先建的行政处罚追责期限及起算"],"qs":["国考 2024 行政执法 行测#11"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"建设项目未依法办理所需环评审批即开工的，“未批先建”行政处罚追责期限从建设行为终了之日起算。行政处罚一般适用二年发现期限，涉及公民生命健康安全或金融安全且有危害后果的延长至五年，法律另有规定的从其规定。","review":{"definition":"建设项目未依法办理所需环评审批即开工的，“未批先建”行政处罚追责期限从建设行为终了之日起算。行政处罚一般适用二年发现期限，涉及公民生命健康安全或金融安全且有危害后果的延长至五年，法律另有规定的从其规定。","explanation":"环保部2018年意见援引的是当时《行政处罚法》第二十九条。2021年修订后，第三十六条沿用了连续或继续状态从行为终了起算的规则，新增了特定情形的五年期限。B项中变电站建成六年后才被发现，题面也未给出适用特别期限的依据，故不能就该次“未批先建”罚款。若存在另外的未验收即投产等行为，应按其各自的违法事实判断。","references":[{"source":"web-fcc231cd27cb48ba","location":"第二部分第（一）、（二）项，追溯期限与起算时间","quote":"应当自建设行为终了之日起计算"},{"source":"web-f8e2c75d89338c50","location":"第三十六条第一、二款","quote":"从行为终了之日起计算"}],"evidence":"某变电站项目建成六年后，乙生态环境局发现其系“未批先建”，处以罚款","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 行政执法 行测#11":{"paper":"国考 2024 行政执法 行测","n":11,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",2],"asrc":["6493f3a6a55c38431852.pdf",4],"card":"09c18159a03e15fe052d6091","links":[{"id":"k-e5c60b39955e2776","role":"直接考查","why":"解析适用自建设行为终了起算的两年期限，判断建成六年后发现的情形能否处罚。"}]}},"terms":{},"references":{"web-fcc231cd27cb48ba":{"name":"环境保护部《关于建设项目“未批先建”违法行为法律适用问题的意见》","url":"https://www.mee.gov.cn/gkml/hbb/bh/201802/t20180228_431889.htm"},"web-f8e2c75d89338c50":{"name":"《中华人民共和国行政处罚法》（2021年修订）","url":"https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/tzsbs/art/2023/art_3712fbfaaed942b3b6b66f14d5288723.html"}},"topics":[],"units":{"k-e5c60b39955e2776":[["国考 2024 行政执法 行测#11"]]}};
